-- 13 Dataset catalog (licensing) + survey_uncertainty side table.
-- Sources: /workspace/dam-refs/CONVENTIONS.md 'Dataset usage' and 'Schema additions (lead, 2026-11-02)';
-- /workspace/dam-refs/procedures/settlement-survey-gnss.md §1 (method codes), §5, §10 (survey_uncertainty), §10.1.
-- Seed: sql/seed/dataset_catalog.csv generated by tools/dataset_catalog.py from the dam-refs manifests
-- (source of truth: datasets/_shared/manifest.csv). Catalog rows are METADATA only - no dataset values.
USE CATALOG IDENTIFIER(:catalog);

CREATE TABLE IF NOT EXISTS ref.dataset_catalog (
  dataset_id        STRING NOT NULL,
  family            STRING COMMENT 'dam-refs/datasets/<family>/manifest.csv',
  title             STRING,
  license           STRING COMMENT 'licence text as recorded in the manifest',
  source_url        STRING,
  usage_restriction STRING NOT NULL COMMENT 'internal-test-only | unrestricted (never blank; CONVENTIONS.md)',
  restriction_basis STRING NOT NULL COMMENT 'manifest value or DERIVED rule used (tools/dataset_catalog.py)',
  manifest_path     STRING,
  loaded_ts         TIMESTAMP,
  CONSTRAINT pk_dataset_catalog PRIMARY KEY (dataset_id)
) TBLPROPERTIES (delta.enableChangeDataFeed = true);
ALTER TABLE ref.dataset_catalog DROP CONSTRAINT IF EXISTS ck_dataset_usage_restriction;
ALTER TABLE ref.dataset_catalog ADD CONSTRAINT ck_dataset_usage_restriction
  CHECK (usage_restriction IN ('internal-test-only', 'unrestricted'));

-- Survey / GNSS point uncertainty (approved side table, lead decision 2026-11-02).
CREATE TABLE IF NOT EXISTS ref.survey_uncertainty (
  point_id     STRING    NOT NULL COMMENT 'survey point / GNSS station; maps to sensor_id prefix <pt> (procedure §10)',
  survey_epoch TIMESTAMP NOT NULL COMMENT 'UTC epoch of the survey / solution',
  method       STRING    NOT NULL COMMENT 'SV-LEV | SV-TS | GN-STATIC | GN-CONT | ... (procedure §1 subtype)',
  sigma_e_mm   DOUBLE COMMENT '1-sigma local East, mm',
  sigma_n_mm   DOUBLE COMMENT '1-sigma local North, mm',
  sigma_u_mm   DOUBLE COMMENT '1-sigma local Up, mm',
  conf_level   DOUBLE    NOT NULL COMMENT 'fraction, e.g. 0.68 (1-sigma) or 0.95 (procedure §10 "confidence_level")',
  source       STRING    NOT NULL COMMENT 'adjustment report, NGL tenv3 sig columns, vendor file, ...',
  dam_id       STRING    NOT NULL COMMENT 'added for row filter / ABAC tag (not in CONVENTIONS column list)',
  created_ts   TIMESTAMP,
  CONSTRAINT pk_survey_uncertainty PRIMARY KEY (point_id, survey_epoch, method)
) TBLPROPERTIES (delta.enableChangeDataFeed = true);
ALTER TABLE ref.survey_uncertainty DROP CONSTRAINT IF EXISTS ck_su_sigma;
ALTER TABLE ref.survey_uncertainty ADD CONSTRAINT ck_su_sigma
  CHECK (coalesce(sigma_e_mm, 0) >= 0 AND coalesce(sigma_n_mm, 0) >= 0 AND coalesce(sigma_u_mm, 0) >= 0);
ALTER TABLE ref.survey_uncertainty DROP CONSTRAINT IF EXISTS ck_su_conf;
ALTER TABLE ref.survey_uncertainty ADD CONSTRAINT ck_su_conf CHECK (conf_level > 0 AND conf_level < 1);
ALTER TABLE ref.survey_uncertainty SET ROW FILTER ref.dam_row_filter ON (dam_id);  -- same filter as 10_security.sql
